window.CODE=window.CODE||{};CODE["day25_rag"]=["<span class=\"cm\"># ============================================================</span>", "<span class=\"cm\"># DAY 25 : RAG WITH REAL FILES - PART 1, THE PDF</span>", "<span class=\"cm\"># ============================================================</span>", "", "<span class=\"cm\"># On Day 22 we built the whole RAG machine. Eight steps, start to finish.</span>", "<span class=\"cm\"># It worked, but it had one very small line hiding in it :</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\">#       if not file_name.endswith(&quot;.txt&quot;):</span>", "<span class=\"cm\">#           continue</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\"># That line is the subject of today&#x27;s class.</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\"># A real company does not keep its knowledge in .txt files. It keeps it in</span>", "<span class=\"cm\"># PDFs, in Word files, in intranet pages, in screenshots somebody pasted into</span>", "<span class=\"cm\"># a chat. Our Day 22 loader walks past every single one of them in silence.</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\"># Look inside plural_labs_docs right now. There are 4 text files, 3 PDFs,</span>", "<span class=\"cm\"># 1 HTML page and 1 screenshot. Day 22 sees 4 files and misses more than half</span>", "<span class=\"cm\"># the company&#x27;s knowledge, and it never prints a single warning while doing it.</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\"># Today we teach it to read PDFs. The next class adds HTML and images.</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\"># Only STEP 1 changes today. Steps 2 to 8 are the same machine as Day 22,</span>", "<span class=\"cm\"># so the comments on those steps are kept short - you already know them.</span>", "<span class=\"cm\"># Everything new is explained in full.</span>", "", "", "<span class=\"cm\"># ------------------------------------------------------------</span>", "<span class=\"cm\"># BEFORE YOU RUN THIS FILE : INSTALL THE NEW PACKAGE</span>", "<span class=\"cm\"># ------------------------------------------------------------</span>", "", "<span class=\"cm\"># On Mac, in the terminal :</span>", "<span class=\"cm\">#     pip3 install pypdf</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\"># On Windows, in the command prompt :</span>", "<span class=\"cm\">#     pip install pypdf</span>", "<span class=\"cm\"># or python3 -m pip install X</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\"># One package today. pypdf is written in pure Python, so it installs on every</span>", "<span class=\"cm\"># machine without needing a compiler. That is exactly why we start with it.</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\"># You will hear about other PDF libraries - PyMuPDF, pdfplumber. They are</span>", "<span class=\"cm\"># faster and they understand page layout better. We will meet PyMuPDF in the</span>", "<span class=\"cm\"># screenshot class, because it can turn a PDF page into an image. For reading</span>", "<span class=\"cm\"># plain text out of a normal PDF, pypdf is the simplest thing that works.</span>", "", "", "<span class=\"cm\"># ------------------------------------------------------------</span>", "<span class=\"cm\"># THE IMPORTS</span>", "<span class=\"cm\"># ------------------------------------------------------------</span>", "", "<span class=\"kc\">import</span> <span class=\"cl\">os</span>", "", "<span class=\"cm\"># re -&gt; Python&#x27;s REGULAR EXPRESSION module. This is probably new to you, so</span>", "<span class=\"cm\"># here is the whole idea in one paragraph before we use it.</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\"># You already know how to find exact text :</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\">#       text.replace(&quot;cat&quot;, &quot;dog&quot;)</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\"># That works when you know exactly what you are looking for. But today we have</span>", "<span class=\"cm\"># to fix messes where we do NOT know the exact text. We need to say things like</span>", "<span class=\"cm\"># &quot;wherever there is a run of spaces and newlines, however long it happens to</span>", "<span class=\"cm\"># be, squash it down to one space&quot;. You cannot write that with .replace(),</span>", "<span class=\"cm\"># because you would have to call it once for two spaces, again for three</span>", "<span class=\"cm\"># spaces, again for a newline followed by two spaces, and so on forever.</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\"># A regular expression - a regex - is a tiny language for describing a SHAPE of</span>", "<span class=\"cm\"># text instead of exact text. &quot;A run of whitespace&quot; is a shape. &quot;A digit</span>", "<span class=\"cm\"># followed by a colon&quot; is a shape. The re module is Python&#x27;s reader for that</span>", "<span class=\"cm\"># language, and it is built into Python, so there is nothing to install.</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\"># We use exactly one function from it today, re.sub, explained where we use it.</span>", "<span class=\"kc\">import</span> <span class=\"cl\">re</span>", "", "<span class=\"cm\"># ---- from pypdf import PdfReader ----</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\"># Look at this line next to the two lines above it. They are both imports,</span>", "<span class=\"cm\"># but they are written in two different shapes, and the difference is worth</span>", "<span class=\"cm\"># understanding because you will write both for the rest of your life.</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\">#       import os                     &lt;- bring in the WHOLE module</span>", "<span class=\"cm\">#       from pypdf import PdfReader   &lt;- bring in ONE NAME out of a package</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\"># With the first shape, everything stays behind its module name, and you must</span>", "<span class=\"cm\"># keep saying os.path.join. With the second shape, the one name you asked for</span>", "<span class=\"cm\"># is dropped straight into your file, so you write PdfReader(...) on its own</span>", "<span class=\"cm\"># rather than pypdf.PdfReader(...).</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\"># Both work. We use the second here because we need exactly one thing out of</span>", "<span class=\"cm\"># pypdf and we mention it twice, so the shorter name is clearer. We use the</span>", "<span class=\"cm\"># first for os because we use many different pieces of it.</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\"># WHERE DID pypdf COME FROM?</span>", "<span class=\"cm\"># os and re came with Python. pypdf did not - you installed it yourself with</span>", "<span class=\"cm\"># pip, and pip put a folder of Python files somewhere Python knows to look.</span>", "<span class=\"cm\"># That is all a &quot;package&quot; is : somebody else&#x27;s Python files on your disk.</span>", "<span class=\"cm\"># Nothing magic, and you can go and read them.</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\"># WHAT IS PdfReader?</span>", "<span class=\"cm\"># It is a CLASS, not a function. That capital-letters-joined-together style is</span>", "<span class=\"cm\"># how Python programmers signal a class - compare PdfReader with os.listdir.</span>", "<span class=\"cm\"># It is a convention, not a rule the language enforces, but it is followed so</span>", "<span class=\"cm\"># consistently that you can read a name and know what it is.</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\"># The practical difference for us : calling a function gives you an answer,</span>", "<span class=\"cm\"># but calling a class gives you an OBJECT - a thing that holds state and has</span>", "<span class=\"cm\"># its own abilities attached to it. So when we write</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\">#       reader = PdfReader(path)</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\"># we are not asking &quot;give me the text&quot;. We are saying &quot;open this PDF and give</span>", "<span class=\"cm\"># me something I can ask questions of&quot;. Then we ask it things :</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\">#       reader.pages                 -&gt; the pages of the document</span>", "<span class=\"cm\">#       len(reader.pages)            -&gt; how many pages there are</span>", "<span class=\"cm\">#       reader.pages[0]              -&gt; the first page</span>", "<span class=\"cm\">#       reader.pages[0].extract_text()  -&gt; the text on that page</span>", "<span class=\"cm\">#       reader.metadata              -&gt; title, author, created date, if present</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\"># ONE HONEST DETAIL. reader.pages looks like a list and you can loop over it,</span>", "<span class=\"cm\"># count it and index it - but it is not actually a list. pypdf hands back its</span>", "<span class=\"cm\"># own object that only parses a page at the moment you reach for it. That is</span>", "<span class=\"cm\"># why opening a 500 page PDF is instant : nothing has really been read yet.</span>", "<span class=\"cm\"># You do not have to do anything about this. It is simply worth knowing that</span>", "<span class=\"cm\"># &quot;behaves like a list&quot; and &quot;is a list&quot; are different claims in Python, and</span>", "<span class=\"cm\"># most code only ever needs the first.</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\"># AND THE LIMIT THAT MATTERS MOST.</span>", "<span class=\"cm\"># extract_text() pulls out the text that is already stored inside the PDF as</span>", "<span class=\"cm\"># text. It does not look at the page and recognise letters. If a page is a</span>", "<span class=\"cm\"># photograph of a document, there is no text in there to pull, and pypdf</span>", "<span class=\"cm\"># returns an empty string - politely, with no error. Our loader checks for</span>", "<span class=\"cm\"># exactly that case further down, and the class after this one is about what</span>", "<span class=\"cm\"># to do when it happens.</span>", "<span class=\"kc\">from</span> <span class=\"va\">pypdf</span> <span class=\"kc\">import</span> <span class=\"cl\">PdfReader</span>", "", "<span class=\"kc\">from</span> <span class=\"va\">langchain_google_genai</span> <span class=\"kc\">import</span> <span class=\"cl\">ChatGoogleGenerativeAI</span>", "<span class=\"kc\">from</span> <span class=\"va\">langchain_google_genai</span> <span class=\"kc\">import</span> <span class=\"cl\">GoogleGenerativeAIEmbeddings</span>", "<span class=\"kc\">from</span> <span class=\"va\">langchain_qdrant</span> <span class=\"kc\">import</span> <span class=\"cl\">QdrantVectorStore</span>", "<span class=\"kc\">from</span> <span class=\"va\">dotenv</span> <span class=\"kc\">import</span> <span class=\"va\">load_dotenv</span>", "", "<span class=\"fn\">load_dotenv</span><span class=\"op\">(</span><span class=\"op\">)</span>", "", "<span class=\"va\">folder</span> <span class=\"op\">=</span> <span class=\"st\">&quot;plural_labs_docs&quot;</span>", "", "", "<span class=\"cm\"># ============================================================</span>", "<span class=\"cm\"># STEP 0 : WHY DAY 22 CANNOT SIMPLY READ A PDF</span>", "<span class=\"cm\"># ============================================================</span>", "", "<span class=\"cm\"># Before we fix anything, let us watch the problem happen.</span>", "<span class=\"cm\"># A beginner&#x27;s first instinct is reasonable : a PDF is a file, open() reads</span>", "<span class=\"cm\"># files, so just open it. Let us try that on one of our new PDFs.</span>", "", "<span class=\"fn\">print</span><span class=\"op\">(</span><span class=\"st\">&quot;STEP 0 - what happens if we read a PDF the Day 22 way&quot;</span><span class=\"op\">)</span>", "", "<span class=\"kc\">try</span><span class=\"op\">:</span>", "    <span class=\"kc\">with</span> <span class=\"fn\">open</span><span class=\"op\">(</span><span class=\"cl\">os</span><span class=\"op\">.</span><span class=\"va\">path</span><span class=\"op\">.</span><span class=\"fn\">join</span><span class=\"op\">(</span><span class=\"va\">folder</span><span class=\"op\">,</span> <span class=\"st\">&quot;remote_work_policy.pdf&quot;</span><span class=\"op\">)</span><span class=\"op\">,</span> <span class=\"st\">&quot;r&quot;</span><span class=\"op\">,</span> <span class=\"va\">encoding</span><span class=\"op\">=</span><span class=\"st\">&quot;utf-8&quot;</span><span class=\"op\">)</span> <span class=\"kc\">as</span> <span class=\"va\">f</span><span class=\"op\">:</span>", "        <span class=\"va\">f</span><span class=\"op\">.</span><span class=\"fn\">read</span><span class=\"op\">(</span><span class=\"op\">)</span>", "<span class=\"kc\">except</span> <span class=\"cl\">UnicodeDecodeError</span> <span class=\"kc\">as</span> <span class=\"va\">error</span><span class=\"op\">:</span>", "    <span class=\"fn\">print</span><span class=\"op\">(</span><span class=\"st\">&quot;    Python refused :&quot;</span><span class=\"op\">,</span> <span class=\"va\">error</span><span class=\"op\">)</span>", "", "<span class=\"cm\"># Read that error message slowly. &quot;codec can&#x27;t decode byte 0xf9&quot;.</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\"># A .txt file is just letters, one after another. A PDF is not. A PDF is a</span>", "<span class=\"cm\"># small compressed database - it holds fonts, images, page sizes, and the text</span>", "<span class=\"cm\"># squeezed down into binary. Those bytes are not letters in any alphabet, so</span>", "<span class=\"cm\"># Python cannot turn them into a string and it stops.</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\"># This is actually the GOOD case, because it is loud. It crashes and tells us.</span>", "<span class=\"cm\"># Later in this course we will meet the quiet case : a file that opens happily</span>", "<span class=\"cm\"># and gives us an empty string. That one is far more dangerous, because the</span>", "<span class=\"cm\"># program keeps running and just quietly knows nothing.</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\"># So we cannot read a PDF ourselves. We need a library that understands the</span>", "<span class=\"cm\"># PDF format and unpacks the text for us. That is pypdf.</span>", "", "<span class=\"fn\">print</span><span class=\"op\">(</span><span class=\"st\">&quot;-&quot;</span> <span class=\"op\">*</span> <span class=\"nu\">60</span><span class=\"op\">)</span>", "", "", "<span class=\"cm\"># ============================================================</span>", "<span class=\"cm\"># PIPELINE 1 - INDEXING</span>", "<span class=\"cm\"># ============================================================</span>", "", "<span class=\"cm\"># ------------------------------------------------------------</span>", "<span class=\"cm\"># STEP 1 : LOAD - now with more than one file format</span>", "<span class=\"cm\"># ------------------------------------------------------------</span>", "", "<span class=\"cm\"># This is the whole lesson. Read it in three parts :</span>", "<span class=\"cm\">#   part A - a function that cleans up text</span>", "<span class=\"cm\">#   part B - one small loader function per file format</span>", "<span class=\"cm\">#   part C - a dictionary that picks the right loader</span>", "", "", "<span class=\"cm\"># ---------- part A : cleaning the text ----------</span>", "", "<span class=\"kb\">def</span> <span class=\"fn\">clean_text</span><span class=\"op\">(</span><span class=\"va\">text</span><span class=\"op\">)</span><span class=\"op\">:</span>", "    <span class=\"st\">&quot;&quot;&quot;Tidy up the raw text that a PDF gives us.&quot;&quot;&quot;</span>", "", "    <span class=\"cm\"># PROBLEM 1 : ligatures.</span>", "    <span class=\"cm\"># Open any PDF of ours and pypdf hands back &quot;E\ufb00ective&quot; and &quot;O\ufb03ce&quot;</span>", "    <span class=\"cm\"># and &quot;Con\ufb01dential&quot;. Those are not typos and pypdf is not broken.</span>", "    <span class=\"cm\">#</span>", "    <span class=\"cm\"># When a typesetter puts certain letters next to each other - f and f, or</span>", "    <span class=\"cm\"># f and i - the font draws them joined together as ONE single character.</span>", "    <span class=\"cm\"># Printers have done this for 500 years because &quot;ff&quot; looks cramped.</span>", "    <span class=\"cm\"># Unicode kept those joined shapes as real characters of their own.</span>", "    <span class=\"cm\"># So inside the PDF, the word &quot;office&quot; is genuinely stored as o + \ufb03 + c + e.</span>", "    <span class=\"cm\"># Five characters, not six.</span>", "    <span class=\"cm\">#</span>", "    <span class=\"cm\"># Why we must care : our search works on meaning, but the embedding model</span>", "    <span class=\"cm\"># still reads characters. &quot;O\ufb03ce&quot; is not the word &quot;office&quot; to it. A student</span>", "    <span class=\"cm\"># asking about the office could easily miss this chunk. So we translate</span>", "    <span class=\"cm\"># those joined characters back into normal letters before anything else.</span>", "    <span class=\"va\">ligatures</span> <span class=\"op\">=</span> <span class=\"op\">{</span>", "        <span class=\"st\">&quot;\ufb00&quot;</span><span class=\"op\">:</span> <span class=\"st\">&quot;ff&quot;</span><span class=\"op\">,</span>    <span class=\"cm\"># as in o\ufb00ice hours, sta\ufb00</span>", "        <span class=\"st\">&quot;\ufb01&quot;</span><span class=\"op\">:</span> <span class=\"st\">&quot;fi&quot;</span><span class=\"op\">,</span>    <span class=\"cm\"># as in con\ufb01dential, bene\ufb01ts</span>", "        <span class=\"st\">&quot;\ufb02&quot;</span><span class=\"op\">:</span> <span class=\"st\">&quot;fl&quot;</span><span class=\"op\">,</span>    <span class=\"cm\"># as in \ufb02exible, re\ufb02ect</span>", "        <span class=\"st\">&quot;\ufb03&quot;</span><span class=\"op\">:</span> <span class=\"st\">&quot;ffi&quot;</span><span class=\"op\">,</span>   <span class=\"cm\"># as in o\ufb03ce, su\ufb03cient</span>", "        <span class=\"st\">&quot;\ufb04&quot;</span><span class=\"op\">:</span> <span class=\"st\">&quot;ffl&quot;</span><span class=\"op\">,</span>   <span class=\"cm\"># as in sha\ufb04e - rare, but costs nothing to handle</span>", "    <span class=\"op\">}</span>", "    <span class=\"kc\">for</span> <span class=\"va\">joined_character</span><span class=\"op\">,</span> <span class=\"va\">normal_letters</span> <span class=\"kc\">in</span> <span class=\"va\">ligatures</span><span class=\"op\">.</span><span class=\"fn\">items</span><span class=\"op\">(</span><span class=\"op\">)</span><span class=\"op\">:</span>", "        <span class=\"va\">text</span> <span class=\"op\">=</span> <span class=\"va\">text</span><span class=\"op\">.</span><span class=\"fn\">replace</span><span class=\"op\">(</span><span class=\"va\">joined_character</span><span class=\"op\">,</span> <span class=\"va\">normal_letters</span><span class=\"op\">)</span>", "", "    <span class=\"cm\"># ----------------------------------------------------------------</span>", "    <span class=\"cm\"># MEET re.sub - it takes THREE arguments</span>", "    <span class=\"cm\">#</span>", "    <span class=\"cm\">#       re.sub(pattern, replacement, text)</span>", "    <span class=\"cm\">#          |       |          |        |</span>", "    <span class=\"cm\">#          |       |          |        +-- the text to work on</span>", "    <span class=\"cm\">#          |       |          +----------- what to put instead</span>", "    <span class=\"cm\">#          |       +---------------------- the SHAPE to look for</span>", "    <span class=\"cm\">#          +------------------------------ &quot;substitute&quot;</span>", "    <span class=\"cm\">#</span>", "    <span class=\"cm\"># It finds every place in the text that matches the shape, and replaces</span>", "    <span class=\"cm\"># all of them. Not the first one - every one. You do not write a loop.</span>", "    <span class=\"cm\">#</span>", "    <span class=\"cm\"># And note how we call it below :</span>", "    <span class=\"cm\">#</span>", "    <span class=\"cm\">#       text = re.sub(...)</span>", "    <span class=\"cm\">#</span>", "    <span class=\"cm\"># The result is ASSIGNED BACK to text. re.sub does not change the text you</span>", "    <span class=\"cm\"># give it, because strings in Python can never be changed once they exist.</span>", "    <span class=\"cm\"># It builds a brand new string and hands it back. If you forget the</span>", "    <span class=\"cm\"># &quot;text =&quot; part, the function runs perfectly, does all the work, and you</span>", "    <span class=\"cm\"># throw the answer away. Nothing crashes. That is a bug students lose</span>", "    <span class=\"cm\"># whole evenings to, so look for it first when cleaning seems to do nothing.</span>", "    <span class=\"cm\"># ----------------------------------------------------------------</span>", "", "    <span class=\"cm\"># PROBLEM 2 : hyphens at the end of a line.</span>", "    <span class=\"cm\">#</span>", "    <span class=\"cm\"># When a document is justified, a long word gets broken across two lines</span>", "    <span class=\"cm\"># with a hyphen : &quot;reimburse-&quot; at the end of one line and &quot;ment&quot; at the</span>", "    <span class=\"cm\"># start of the next. The PDF stores it exactly like that, so pypdf gives us</span>", "    <span class=\"cm\">#</span>", "    <span class=\"cm\">#       &quot;reimburse-\\nment&quot;</span>", "    <span class=\"cm\">#</span>", "    <span class=\"cm\"># and our search would then be looking for a word that does not exist.</span>", "    <span class=\"cm\"># Glue it back together by deleting the hyphen and the newline.</span>", "    <span class=\"cm\">#</span>", "    <span class=\"cm\"># Reading the pattern r&quot;-\\n&quot; :</span>", "    <span class=\"cm\">#       -       an ordinary hyphen, matching itself</span>", "    <span class=\"cm\">#       \\n      a newline, the invisible character at the end of a line</span>", "    <span class=\"cm\">#</span>", "    <span class=\"cm\"># The replacement is &quot;&quot; - an empty string - which is how you say &quot;delete</span>", "    <span class=\"cm\"># this&quot; with re.sub. There is no separate delete function; replacing</span>", "    <span class=\"cm\"># something with nothing IS deleting it.</span>", "    <span class=\"cm\">#</span>", "    <span class=\"cm\"># HONESTY NOTE, and a habit worth copying : this rule finds nothing in our</span>", "    <span class=\"cm\"># three PDFs. I counted - zero matches - because the tool that made them</span>", "    <span class=\"cm\"># does not hyphenate. It fires constantly on PDFs exported from Word or</span>", "    <span class=\"cm\"># from LaTeX. Keeping a rule that does nothing today costs us nothing and</span>", "    <span class=\"cm\"># saves us the day a student brings in a real company document. But do go</span>", "    <span class=\"cm\"># and count, rather than assuming your cleaning worked :</span>", "    <span class=\"cm\">#</span>", "    <span class=\"cm\">#       print(len(re.findall(r&quot;-\\n&quot;, raw_text)))</span>", "    <span class=\"va\">text</span> <span class=\"op\">=</span> <span class=\"cl\">re</span><span class=\"op\">.</span><span class=\"fn\">sub</span><span class=\"op\">(</span><span class=\"st\">r&quot;-\\n&quot;</span><span class=\"op\">,</span> <span class=\"st\">&quot;&quot;</span><span class=\"op\">,</span> <span class=\"va\">text</span><span class=\"op\">)</span>", "", "    <span class=\"cm\"># PROBLEM 3 : ragged whitespace. This is the rule that does the real work.</span>", "    <span class=\"cm\">#</span>", "    <span class=\"cm\"># A PDF does not store sentences. It stores instructions like &quot;draw these</span>", "    <span class=\"cm\"># letters at this position on the page&quot;. So where a sentence happens to</span>", "    <span class=\"cm\"># reach the right margin, the PDF simply starts the next line, and pypdf</span>", "    <span class=\"cm\"># hands that back to us as a newline sitting in the middle of a sentence.</span>", "    <span class=\"cm\"># One of our own pages genuinely contains this :</span>", "    <span class=\"cm\">#</span>", "    <span class=\"cm\">#       &quot;Do not turn it off. Your\\nscreen must lock automatically&quot;</span>", "    <span class=\"cm\">#</span>", "    <span class=\"cm\"># Our handbook has 45 of those. Column layouts and tables are worse again,</span>", "    <span class=\"cm\"># and give long runs of spaces in the middle of a line.</span>", "    <span class=\"cm\">#</span>", "    <span class=\"cm\"># Reading the pattern r&quot;\\s+&quot; :</span>", "    <span class=\"cm\">#       \\s      ONE whitespace character - a space, a tab, or a newline</span>", "    <span class=\"cm\">#       +       &quot;one or more of the thing just before me&quot;</span>", "    <span class=\"cm\">#   so  \\s+     a run of whitespace of ANY length, from one to a thousand</span>", "    <span class=\"cm\">#</span>", "    <span class=\"cm\"># Replacing all of it with a single &quot; &quot; turns any mess of spacing into one</span>", "    <span class=\"cm\"># ordinary space. &quot;it off. Your\\nscreen&quot; becomes &quot;it off. Your screen&quot;.</span>", "    <span class=\"cm\">#</span>", "    <span class=\"cm\"># WHY THE LITTLE r BEFORE THE QUOTES?</span>", "    <span class=\"cm\"># That r makes it a RAW string, and it is not decoration. Inside a normal</span>", "    <span class=\"cm\"># Python string a backslash starts an escape code - &quot;\\n&quot; means newline,</span>", "    <span class=\"cm\"># &quot;\\t&quot; means tab. But &quot;\\s&quot; is not an escape code Python knows, and Python</span>", "    <span class=\"cm\"># 3.14 will tell you so :</span>", "    <span class=\"cm\">#</span>", "    <span class=\"cm\">#       SyntaxWarning: &quot;\\s&quot; is an invalid escape sequence.</span>", "    <span class=\"cm\">#</span>", "    <span class=\"cm\"># The r switches that whole system off and passes the characters through</span>", "    <span class=\"cm\"># untouched, so the regex engine receives \\ and s and reads them as its own</span>", "    <span class=\"cm\"># code for whitespace. Habit to build : if a string is a regex, start it</span>", "    <span class=\"cm\"># with r, every time, without thinking about it.</span>", "    <span class=\"va\">text</span> <span class=\"op\">=</span> <span class=\"cl\">re</span><span class=\"op\">.</span><span class=\"fn\">sub</span><span class=\"op\">(</span><span class=\"st\">r&quot;\\s+&quot;</span><span class=\"op\">,</span> <span class=\"st\">&quot; &quot;</span><span class=\"op\">,</span> <span class=\"va\">text</span><span class=\"op\">)</span>", "", "    <span class=\"cm\"># ORDER MATTERS, and this is the kind of thing that makes cleaning code</span>", "    <span class=\"cm\"># look simple and behave strangely. Problem 2 must run BEFORE problem 3.</span>", "    <span class=\"cm\"># Once problem 3 has turned every newline into a space, &quot;reimburse-\\nment&quot;</span>", "    <span class=\"cm\"># has already become &quot;reimburse- ment&quot;, and the pattern r&quot;-\\n&quot; can never</span>", "    <span class=\"cm\"># match it again. Swap these two lines and the hyphen fix silently stops</span>", "    <span class=\"cm\"># working - with no error, which is exactly why you must notice it now.</span>", "", "    <span class=\"cm\"># .strip() -&gt; remove leading and trailing spaces</span>", "    <span class=\"kc\">return</span> <span class=\"va\">text</span><span class=\"op\">.</span><span class=\"fn\">strip</span><span class=\"op\">(</span><span class=\"op\">)</span>", "", "", "<span class=\"cm\"># ---------- part B : one loader per file format ----------</span>", "", "<span class=\"cm\"># Every loader below follows the SAME contract, and the contract is the point.</span>", "<span class=\"cm\"># Each one takes a file path and returns a LIST of dictionaries, where each</span>", "<span class=\"cm\"># dictionary is {&quot;page&quot;: &lt;number or None&gt;, &quot;text&quot;: &lt;the text&gt;}.</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\"># Why a list, when a text file has only one piece of text in it?</span>", "<span class=\"cm\"># Because a PDF has many. If we return a list from every loader, then the code</span>", "<span class=\"cm\"># that calls them never has to care which format it is dealing with. One file</span>", "<span class=\"cm\"># gives us one list, whether that list has 1 item or 400.</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\"># That idea - every loader looks identical from the outside - is what will let</span>", "<span class=\"cm\"># us add HTML and images next class by writing one function and changing</span>", "<span class=\"cm\"># nothing else in this file.</span>", "", "", "<span class=\"kb\">def</span> <span class=\"fn\">load_txt</span><span class=\"op\">(</span><span class=\"va\">path</span><span class=\"op\">)</span><span class=\"op\">:</span>", "    <span class=\"st\">&quot;&quot;&quot;Read a plain text file. This is Day 22&#x27;s loader, unchanged.&quot;&quot;&quot;</span>", "    <span class=\"kc\">with</span> <span class=\"fn\">open</span><span class=\"op\">(</span><span class=\"va\">path</span><span class=\"op\">,</span> <span class=\"st\">&quot;r&quot;</span><span class=\"op\">,</span> <span class=\"va\">encoding</span><span class=\"op\">=</span><span class=\"st\">&quot;utf-8&quot;</span><span class=\"op\">)</span> <span class=\"kc\">as</span> <span class=\"va\">file</span><span class=\"op\">:</span>", "        <span class=\"va\">text</span> <span class=\"op\">=</span> <span class=\"va\">file</span><span class=\"op\">.</span><span class=\"fn\">read</span><span class=\"op\">(</span><span class=\"op\">)</span>", "", "    <span class=\"cm\"># page is None because a text file has no pages. Nothing to number.</span>", "    <span class=\"cm\"># We will handle that None when we print the source at the end.</span>", "    <span class=\"kc\">return</span> <span class=\"op\">[</span><span class=\"op\">{</span><span class=\"st\">&quot;page&quot;</span><span class=\"op\">:</span> <span class=\"kb\">None</span><span class=\"op\">,</span> <span class=\"st\">&quot;text&quot;</span><span class=\"op\">:</span> <span class=\"fn\">clean_text</span><span class=\"op\">(</span><span class=\"va\">text</span><span class=\"op\">)</span><span class=\"op\">}</span><span class=\"op\">]</span>", "", "", "<span class=\"kb\">def</span> <span class=\"fn\">load_pdf</span><span class=\"op\">(</span><span class=\"va\">path</span><span class=\"op\">)</span><span class=\"op\">:</span>", "    <span class=\"st\">&quot;&quot;&quot;Read a PDF, one entry per page.&quot;&quot;&quot;</span>", "", "    <span class=\"cm\"># PdfReader opens the file and understands its structure for us.</span>", "    <span class=\"va\">reader</span> <span class=\"op\">=</span> <span class=\"cl\">PdfReader</span><span class=\"op\">(</span><span class=\"va\">path</span><span class=\"op\">)</span>", "", "    <span class=\"va\">pages</span> <span class=\"op\">=</span> <span class=\"op\">[</span><span class=\"op\">]</span>", "", "    <span class=\"cm\"># reader.pages behaves like a list of page objects.</span>", "    <span class=\"cm\"># enumerate(..., start=1) gives us the position as we go, counting from 1</span>", "    <span class=\"cm\"># instead of 0 - because a human reading page one calls it page 1.</span>", "    <span class=\"kc\">for</span> <span class=\"va\">page_number</span><span class=\"op\">,</span> <span class=\"va\">page</span> <span class=\"kc\">in</span> <span class=\"fn\">enumerate</span><span class=\"op\">(</span><span class=\"va\">reader</span><span class=\"op\">.</span><span class=\"va\">pages</span><span class=\"op\">,</span> <span class=\"va\">start</span><span class=\"op\">=</span><span class=\"nu\">1</span><span class=\"op\">)</span><span class=\"op\">:</span>", "", "        <span class=\"cm\"># extract_text() -&gt; pulls the text out of that one page.</span>", "        <span class=\"cm\"># It can return None for a page that has no text layer at all,</span>", "        <span class=\"cm\"># so &quot;or empty string&quot; protects us from a crash on the next line.</span>", "        <span class=\"va\">raw_text</span> <span class=\"op\">=</span> <span class=\"va\">page</span><span class=\"op\">.</span><span class=\"fn\">extract_text</span><span class=\"op\">(</span><span class=\"op\">)</span> <span class=\"kc\">or</span> <span class=\"st\">&quot;&quot;</span>", "", "        <span class=\"va\">text</span> <span class=\"op\">=</span> <span class=\"fn\">clean_text</span><span class=\"op\">(</span><span class=\"va\">raw_text</span><span class=\"op\">)</span>", "", "        <span class=\"cm\"># THE EMPTY PAGE CHECK.</span>", "        <span class=\"cm\"># If a page gives us almost nothing, something is wrong with it.</span>", "        <span class=\"cm\"># Usually it means the page is a SCANNED IMAGE - somebody photocopied</span>", "        <span class=\"cm\"># a document and saved the photo inside a PDF. There are no letters in</span>", "        <span class=\"cm\"># that file at all, only a picture of letters. pypdf is not failing;</span>", "        <span class=\"cm\"># there is genuinely nothing there for it to find.</span>", "        <span class=\"cm\">#</span>", "        <span class=\"cm\"># We cannot fix that today, but we must never let it pass in silence.</span>", "        <span class=\"cm\"># An empty chunk in our database is worse than no chunk, because it</span>", "        <span class=\"cm\"># still takes up one of the 3 slots our search returns.</span>", "        <span class=\"cm\"># Next class we send pages like this to a vision model to be read.</span>", "        <span class=\"kc\">if</span> <span class=\"fn\">len</span><span class=\"op\">(</span><span class=\"va\">text</span><span class=\"op\">)</span> <span class=\"op\">&lt;</span> <span class=\"nu\">100</span><span class=\"op\">:</span>", "            <span class=\"fn\">print</span><span class=\"op\">(</span><span class=\"st\">&quot;    WARNING :&quot;</span><span class=\"op\">,</span> <span class=\"cl\">os</span><span class=\"op\">.</span><span class=\"va\">path</span><span class=\"op\">.</span><span class=\"fn\">basename</span><span class=\"op\">(</span><span class=\"va\">path</span><span class=\"op\">)</span><span class=\"op\">,</span> <span class=\"st\">&quot;page&quot;</span><span class=\"op\">,</span> <span class=\"va\">page_number</span><span class=\"op\">,</span>", "                  <span class=\"st\">&quot;gave only&quot;</span><span class=\"op\">,</span> <span class=\"fn\">len</span><span class=\"op\">(</span><span class=\"va\">text</span><span class=\"op\">)</span><span class=\"op\">,</span> <span class=\"st\">&quot;characters - is it a scan?&quot;</span><span class=\"op\">)</span>", "            <span class=\"kc\">continue</span>", "", "        <span class=\"va\">pages</span><span class=\"op\">.</span><span class=\"fn\">append</span><span class=\"op\">(</span><span class=\"op\">{</span><span class=\"st\">&quot;page&quot;</span><span class=\"op\">:</span> <span class=\"va\">page_number</span><span class=\"op\">,</span> <span class=\"st\">&quot;text&quot;</span><span class=\"op\">:</span> <span class=\"va\">text</span><span class=\"op\">}</span><span class=\"op\">)</span>", "", "    <span class=\"kc\">return</span> <span class=\"va\">pages</span>", "", "", "<span class=\"cm\"># ---------- part C : the dictionary that chooses ----------</span>", "", "<span class=\"cm\"># Here is the idea that replaces Day 22&#x27;s if-statement.</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\"># We already know a dictionary can hold numbers or strings as its values.</span>", "<span class=\"cm\"># A dictionary can also hold FUNCTIONS as its values. Look carefully at what</span>", "<span class=\"cm\"># is written below : load_txt, with no brackets after it.</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\">#     load_txt()  -&gt; brackets mean CALL the function right now, give me the result</span>", "<span class=\"cm\">#     load_txt    -&gt; no brackets means the function ITSELF, as a value</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\"># So LOADERS is a dictionary from a file extension to the function that knows</span>", "<span class=\"cm\"># how to read it. People call this a dispatch table, or a registry.</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\"># Why this is better than a chain of if-elif-elif :</span>", "<span class=\"cm\">#   - adding a format is adding ONE line, not editing a growing if-block</span>", "<span class=\"cm\">#   - the list of what we support is visible in one place, at a glance</span>", "<span class=\"cm\">#   - the loop below never mentions pdf or txt at all, so it never changes</span>", "", "<span class=\"co\">LOADERS</span> <span class=\"op\">=</span> <span class=\"op\">{</span>", "    <span class=\"st\">&quot;.txt&quot;</span><span class=\"op\">:</span> <span class=\"va\">load_txt</span><span class=\"op\">,</span>", "    <span class=\"st\">&quot;.md&quot;</span><span class=\"op\">:</span>  <span class=\"va\">load_txt</span><span class=\"op\">,</span>   <span class=\"cm\"># a markdown file is plain text too, so the same loader works</span>", "    <span class=\"st\">&quot;.pdf&quot;</span><span class=\"op\">:</span> <span class=\"va\">load_pdf</span><span class=\"op\">,</span>", "<span class=\"op\">}</span>", "", "", "<span class=\"cm\"># ---------- and now the loading loop ----------</span>", "", "<span class=\"va\">documents</span> <span class=\"op\">=</span> <span class=\"op\">[</span><span class=\"op\">]</span>", "", "<span class=\"kc\">for</span> <span class=\"va\">file_name</span> <span class=\"kc\">in</span> <span class=\"fn\">sorted</span><span class=\"op\">(</span><span class=\"cl\">os</span><span class=\"op\">.</span><span class=\"fn\">listdir</span><span class=\"op\">(</span><span class=\"va\">folder</span><span class=\"op\">)</span><span class=\"op\">)</span><span class=\"op\">:</span>", "", "    <span class=\"cm\"># os.path.splitext splits a name into two parts at the last dot.</span>", "    <span class=\"cm\"># &quot;remote_work_policy.pdf&quot; becomes (&quot;remote_work_policy&quot;, &quot;.pdf&quot;)</span>", "    <span class=\"cm\"># The [1] takes the second part, the extension.</span>", "    <span class=\"cm\"># .lower() because a file called NOTES.PDF must work exactly the same way.</span>", "    <span class=\"va\">extension</span> <span class=\"op\">=</span> <span class=\"cl\">os</span><span class=\"op\">.</span><span class=\"va\">path</span><span class=\"op\">.</span><span class=\"fn\">splitext</span><span class=\"op\">(</span><span class=\"va\">file_name</span><span class=\"op\">)</span><span class=\"op\">[</span><span class=\"nu\">1</span><span class=\"op\">]</span><span class=\"op\">.</span><span class=\"fn\">lower</span><span class=\"op\">(</span><span class=\"op\">)</span>", "", "    <span class=\"cm\"># .get() asks the dictionary for a value WITHOUT crashing if the key is</span>", "    <span class=\"cm\"># missing. A plain LOADERS[extension] would raise KeyError on our .html</span>", "    <span class=\"cm\"># file. .get() returns None instead, and we can deal with None ourselves.</span>", "    <span class=\"va\">loader</span> <span class=\"op\">=</span> <span class=\"co\">LOADERS</span><span class=\"op\">.</span><span class=\"fn\">get</span><span class=\"op\">(</span><span class=\"va\">extension</span><span class=\"op\">)</span>", "", "    <span class=\"kc\">if</span> <span class=\"va\">loader</span> <span class=\"kc\">is</span> <span class=\"kb\">None</span><span class=\"op\">:</span>", "        <span class=\"cm\"># Day 22 skipped these silently. We refuse to. A loud skip is a to-do</span>", "        <span class=\"cm\"># list - it is literally printing next class&#x27;s homework on the screen.</span>", "        <span class=\"fn\">print</span><span class=\"op\">(</span><span class=\"st\">&quot;    skipping&quot;</span><span class=\"op\">,</span> <span class=\"va\">file_name</span><span class=\"op\">,</span> <span class=\"st\">&quot;- no loader for&quot;</span><span class=\"op\">,</span> <span class=\"va\">extension</span><span class=\"op\">,</span> <span class=\"st\">&quot;yet&quot;</span><span class=\"op\">)</span>", "        <span class=\"kc\">continue</span>", "", "    <span class=\"va\">file_path</span> <span class=\"op\">=</span> <span class=\"cl\">os</span><span class=\"op\">.</span><span class=\"va\">path</span><span class=\"op\">.</span><span class=\"fn\">join</span><span class=\"op\">(</span><span class=\"va\">folder</span><span class=\"op\">,</span> <span class=\"va\">file_name</span><span class=\"op\">)</span>", "", "    <span class=\"cm\"># THE CALL. Note that we do not write load_pdf(file_path) anywhere.</span>", "    <span class=\"cm\"># We write loader(file_path), and the dictionary already decided which</span>", "    <span class=\"cm\"># function &quot;loader&quot; is. This one line reads every format we support.</span>", "    <span class=\"va\">pieces</span> <span class=\"op\">=</span> <span class=\"fn\">loader</span><span class=\"op\">(</span><span class=\"va\">file_path</span><span class=\"op\">)</span>", "", "    <span class=\"cm\"># Each loader gave us a list. We attach the file name to every piece and</span>", "    <span class=\"cm\"># collect them all into one flat list of documents.</span>", "    <span class=\"kc\">for</span> <span class=\"va\">piece</span> <span class=\"kc\">in</span> <span class=\"va\">pieces</span><span class=\"op\">:</span>", "        <span class=\"va\">documents</span><span class=\"op\">.</span><span class=\"fn\">append</span><span class=\"op\">(</span><span class=\"op\">{</span>", "            <span class=\"st\">&quot;source&quot;</span><span class=\"op\">:</span> <span class=\"va\">file_name</span><span class=\"op\">,</span>", "            <span class=\"st\">&quot;page&quot;</span><span class=\"op\">:</span>   <span class=\"va\">piece</span><span class=\"op\">[</span><span class=\"st\">&quot;page&quot;</span><span class=\"op\">]</span><span class=\"op\">,</span>", "            <span class=\"st\">&quot;text&quot;</span><span class=\"op\">:</span>   <span class=\"va\">piece</span><span class=\"op\">[</span><span class=\"st\">&quot;text&quot;</span><span class=\"op\">]</span><span class=\"op\">,</span>", "        <span class=\"op\">}</span><span class=\"op\">)</span>", "", "    <span class=\"fn\">print</span><span class=\"op\">(</span><span class=\"st\">&quot;    loaded&quot;</span><span class=\"op\">,</span> <span class=\"va\">file_name</span><span class=\"op\">,</span> <span class=\"st\">&quot;-&gt;&quot;</span><span class=\"op\">,</span> <span class=\"fn\">len</span><span class=\"op\">(</span><span class=\"va\">pieces</span><span class=\"op\">)</span><span class=\"op\">,</span> <span class=\"st\">&quot;piece(s)&quot;</span><span class=\"op\">)</span>", "", "<span class=\"fn\">print</span><span class=\"op\">(</span><span class=\"st\">&quot;STEP 1 - LOAD :&quot;</span><span class=\"op\">,</span> <span class=\"fn\">len</span><span class=\"op\">(</span><span class=\"va\">documents</span><span class=\"op\">)</span><span class=\"op\">,</span> <span class=\"st\">&quot;pieces of text from&quot;</span><span class=\"op\">,</span> <span class=\"va\">folder</span><span class=\"op\">)</span>", "", "", "<span class=\"cm\"># A small helper for printing where something came from.</span>", "<span class=\"cm\"># A PDF piece can say &quot;page 2&quot;. A text file piece cannot, so it just says the</span>", "<span class=\"cm\"># file name. This is the one place that None has to be handled, and we keep it</span>", "<span class=\"cm\"># in a function so the rest of the file stays clean.</span>", "<span class=\"kb\">def</span> <span class=\"fn\">describe_source</span><span class=\"op\">(</span><span class=\"va\">source</span><span class=\"op\">,</span> <span class=\"va\">page</span><span class=\"op\">)</span><span class=\"op\">:</span>", "    <span class=\"kc\">if</span> <span class=\"va\">page</span> <span class=\"kc\">is</span> <span class=\"kb\">None</span><span class=\"op\">:</span>", "        <span class=\"kc\">return</span> <span class=\"va\">source</span>", "    <span class=\"kc\">return</span> <span class=\"va\">source</span> <span class=\"op\">+</span> <span class=\"st\">&quot; page &quot;</span> <span class=\"op\">+</span> <span class=\"fn\">str</span><span class=\"op\">(</span><span class=\"va\">page</span><span class=\"op\">)</span>", "", "", "<span class=\"fn\">print</span><span class=\"op\">(</span><span class=\"st\">&quot;-&quot;</span> <span class=\"op\">*</span> <span class=\"nu\">60</span><span class=\"op\">)</span>", "", "", "<span class=\"cm\"># ------------------------------------------------------------</span>", "<span class=\"cm\"># STEP 2 : CHUNK</span>", "<span class=\"cm\"># ------------------------------------------------------------</span>", "", "<span class=\"cm\"># Same 60-word cutting as Day 22. We are deliberately not improving the</span>", "<span class=\"cm\"># chunking today - one change per class, so you can always see what caused</span>", "<span class=\"cm\"># what. Chunking gets a full class of its own next.</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\"># ONE thing is new here, and it is small but important. In Day 22 the label</span>", "<span class=\"cm\"># carried only the file name. Now it carries the page number too, and it</span>", "<span class=\"cm\"># carries it all the way through the database to the final answer. That is how</span>", "<span class=\"cm\"># our bot will be able to say &quot;page 2&quot; instead of just naming a 40 page PDF</span>", "<span class=\"cm\"># and leaving you to search it yourself.</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\"># Notice also that because we loaded page by page, a chunk can never contain</span>", "<span class=\"cm\"># text from two different pages. The page split did half of our chunking for</span>", "<span class=\"cm\"># us, for free.</span>", "", "<span class=\"va\">chunk_size</span> <span class=\"op\">=</span> <span class=\"nu\">60</span>", "", "<span class=\"va\">chunk_texts</span> <span class=\"op\">=</span> <span class=\"op\">[</span><span class=\"op\">]</span>", "<span class=\"va\">chunk_labels</span> <span class=\"op\">=</span> <span class=\"op\">[</span><span class=\"op\">]</span>", "", "<span class=\"kc\">for</span> <span class=\"va\">document</span> <span class=\"kc\">in</span> <span class=\"va\">documents</span><span class=\"op\">:</span>", "    <span class=\"va\">words</span> <span class=\"op\">=</span> <span class=\"va\">document</span><span class=\"op\">[</span><span class=\"st\">&quot;text&quot;</span><span class=\"op\">]</span><span class=\"op\">.</span><span class=\"fn\">split</span><span class=\"op\">(</span><span class=\"op\">)</span>", "", "    <span class=\"kc\">for</span> <span class=\"va\">start</span> <span class=\"kc\">in</span> <span class=\"fn\">range</span><span class=\"op\">(</span><span class=\"nu\">0</span><span class=\"op\">,</span> <span class=\"fn\">len</span><span class=\"op\">(</span><span class=\"va\">words</span><span class=\"op\">)</span><span class=\"op\">,</span> <span class=\"va\">chunk_size</span><span class=\"op\">)</span><span class=\"op\">:</span>", "        <span class=\"va\">piece_text</span> <span class=\"op\">=</span> <span class=\"st\">&quot; &quot;</span><span class=\"op\">.</span><span class=\"fn\">join</span><span class=\"op\">(</span><span class=\"va\">words</span><span class=\"op\">[</span><span class=\"va\">start</span><span class=\"op\">:</span><span class=\"va\">start</span> <span class=\"op\">+</span> <span class=\"va\">chunk_size</span><span class=\"op\">]</span><span class=\"op\">)</span>", "", "        <span class=\"va\">chunk_texts</span><span class=\"op\">.</span><span class=\"fn\">append</span><span class=\"op\">(</span><span class=\"va\">piece_text</span><span class=\"op\">)</span>", "        <span class=\"va\">chunk_labels</span><span class=\"op\">.</span><span class=\"fn\">append</span><span class=\"op\">(</span><span class=\"op\">{</span>", "            <span class=\"st\">&quot;source&quot;</span><span class=\"op\">:</span> <span class=\"va\">document</span><span class=\"op\">[</span><span class=\"st\">&quot;source&quot;</span><span class=\"op\">]</span><span class=\"op\">,</span>", "            <span class=\"st\">&quot;page&quot;</span><span class=\"op\">:</span>   <span class=\"va\">document</span><span class=\"op\">[</span><span class=\"st\">&quot;page&quot;</span><span class=\"op\">]</span><span class=\"op\">,</span>      <span class=\"cm\"># &lt;- the new part</span>", "        <span class=\"op\">}</span><span class=\"op\">)</span>", "", "<span class=\"fn\">print</span><span class=\"op\">(</span><span class=\"st\">&quot;STEP 2 - CHUNK : cut into&quot;</span><span class=\"op\">,</span> <span class=\"fn\">len</span><span class=\"op\">(</span><span class=\"va\">chunk_texts</span><span class=\"op\">)</span><span class=\"op\">,</span> <span class=\"st\">&quot;chunks&quot;</span><span class=\"op\">)</span>", "", "", "<span class=\"cm\"># ------------------------------------------------------------</span>", "<span class=\"cm\"># STEP 3 and 4 : EMBED and STORE</span>", "<span class=\"cm\"># ------------------------------------------------------------</span>", "", "<span class=\"cm\"># Unchanged from Day 22. Qdrant calls the embedding model for every chunk and</span>", "<span class=\"cm\"># stores each vector together with its label.</span>", "", "<span class=\"va\">embedding_model</span> <span class=\"op\">=</span> <span class=\"cl\">GoogleGenerativeAIEmbeddings</span><span class=\"op\">(</span><span class=\"va\">model</span><span class=\"op\">=</span><span class=\"st\">&quot;gemini-embedding-001&quot;</span><span class=\"op\">)</span>", "", "<span class=\"va\">vector_db</span> <span class=\"op\">=</span> <span class=\"cl\">QdrantVectorStore</span><span class=\"op\">.</span><span class=\"fn\">from_texts</span><span class=\"op\">(</span>", "    <span class=\"va\">texts</span><span class=\"op\">=</span><span class=\"va\">chunk_texts</span><span class=\"op\">,</span>", "    <span class=\"va\">embedding</span><span class=\"op\">=</span><span class=\"va\">embedding_model</span><span class=\"op\">,</span>", "    <span class=\"va\">metadatas</span><span class=\"op\">=</span><span class=\"va\">chunk_labels</span><span class=\"op\">,</span>", "    <span class=\"va\">collection_name</span><span class=\"op\">=</span><span class=\"st\">&quot;plural_labs&quot;</span><span class=\"op\">,</span>", "    <span class=\"va\">location</span><span class=\"op\">=</span><span class=\"st\">&quot;:memory:&quot;</span><span class=\"op\">,</span>", "<span class=\"op\">)</span>", "", "<span class=\"fn\">print</span><span class=\"op\">(</span><span class=\"st\">&quot;STEP 3 and 4 - EMBED and STORE : Qdrant ready with&quot;</span><span class=\"op\">,</span> <span class=\"fn\">len</span><span class=\"op\">(</span><span class=\"va\">chunk_texts</span><span class=\"op\">)</span><span class=\"op\">,</span> <span class=\"st\">&quot;vectors&quot;</span><span class=\"op\">)</span>", "<span class=\"fn\">print</span><span class=\"op\">(</span><span class=\"st\">&quot;-&quot;</span> <span class=\"op\">*</span> <span class=\"nu\">60</span><span class=\"op\">)</span>", "", "", "<span class=\"cm\"># ============================================================</span>", "<span class=\"cm\"># PIPELINE 2 - ANSWERING</span>", "<span class=\"cm\"># ============================================================</span>", "", "<span class=\"cm\"># THE QUESTION.</span>", "<span class=\"cm\"># This exact question was the last demo of Day 22, and Day 22 could not answer</span>", "<span class=\"cm\"># it. Our bot correctly refused, because the work from home rules were simply</span>", "<span class=\"cm\"># not in any of the four text files.</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\"># Nothing about our retrieval or our prompt has improved since then. The only</span>", "<span class=\"cm\"># thing that changed is that the loader can now open a PDF. Watch the same</span>", "<span class=\"cm\"># question get a real answer.</span>", "", "<span class=\"va\">question</span> <span class=\"op\">=</span> <span class=\"st\">&quot;Can I work from home permanently at Plural Labs?&quot;</span>", "", "<span class=\"cm\"># In class, try these one at a time.</span>", "", "<span class=\"cm\"># Needs page 1 of the remote work PDF :</span>", "<span class=\"cm\"># question = &quot;How much is the home office setup allowance and by when must I claim it?&quot;</span>", "", "<span class=\"cm\"># Needs the IT security PDF :</span>", "<span class=\"cm\"># question = &quot;How long before my laptop screen locks, and can I change it?&quot;</span>", "", "<span class=\"cm\"># Needs the insurance PDF :</span>", "<span class=\"cm\"># question = &quot;Are my parents covered by the company health insurance?&quot;</span>", "", "<span class=\"cm\"># A text file question, to prove we did not break Day 22 while adding PDFs :</span>", "<span class=\"cm\"># question = &quot;How many paid leaves do I get in a year?&quot;</span>", "", "<span class=\"cm\"># This one crosses TWO files - the leave policy text file and the remote work</span>", "<span class=\"cm\"># PDF. Watch how it handles needing evidence from both :</span>", "<span class=\"cm\"># question = &quot;I am a new joiner. Can I work remotely, and how many leaves do I get?&quot;</span>", "", "<span class=\"cm\"># And the honesty test again. Notice period is in none of our 9 files,</span>", "<span class=\"cm\"># not even the new ones. It must still refuse.</span>", "<span class=\"cm\"># question = &quot;What is the notice period if I resign from Plural Labs?&quot;</span>", "", "<span class=\"fn\">print</span><span class=\"op\">(</span><span class=\"st\">&quot;QUESTION :&quot;</span><span class=\"op\">,</span> <span class=\"va\">question</span><span class=\"op\">)</span>", "<span class=\"fn\">print</span><span class=\"op\">(</span><span class=\"st\">&quot;-&quot;</span> <span class=\"op\">*</span> <span class=\"nu\">60</span><span class=\"op\">)</span>", "", "", "<span class=\"cm\"># ------------------------------------------------------------</span>", "<span class=\"cm\"># STEP 5 and 6 : RETRIEVE and RANK</span>", "<span class=\"cm\"># ------------------------------------------------------------</span>", "", "<span class=\"va\">top_chunks</span> <span class=\"op\">=</span> <span class=\"va\">vector_db</span><span class=\"op\">.</span><span class=\"fn\">similarity_search_with_score</span><span class=\"op\">(</span><span class=\"va\">question</span><span class=\"op\">,</span> <span class=\"va\">k</span><span class=\"op\">=</span><span class=\"nu\">3</span><span class=\"op\">)</span>", "", "<span class=\"fn\">print</span><span class=\"op\">(</span><span class=\"st\">&quot;STEP 5 and 6 - RETRIEVE and RANK : the 3 winning chunks are&quot;</span><span class=\"op\">)</span>", "", "<span class=\"kc\">for</span> <span class=\"va\">document</span><span class=\"op\">,</span> <span class=\"va\">score</span> <span class=\"kc\">in</span> <span class=\"va\">top_chunks</span><span class=\"op\">:</span>", "    <span class=\"cm\"># metadata[&quot;page&quot;] is the page number we carried all the way from STEP 1.</span>", "    <span class=\"va\">where</span> <span class=\"op\">=</span> <span class=\"fn\">describe_source</span><span class=\"op\">(</span><span class=\"va\">document</span><span class=\"op\">.</span><span class=\"va\">metadata</span><span class=\"op\">[</span><span class=\"st\">&quot;source&quot;</span><span class=\"op\">]</span><span class=\"op\">,</span> <span class=\"va\">document</span><span class=\"op\">.</span><span class=\"va\">metadata</span><span class=\"op\">[</span><span class=\"st\">&quot;page&quot;</span><span class=\"op\">]</span><span class=\"op\">)</span>", "    <span class=\"fn\">print</span><span class=\"op\">(</span><span class=\"st\">&quot;   &quot;</span><span class=\"op\">,</span> <span class=\"fn\">round</span><span class=\"op\">(</span><span class=\"va\">score</span><span class=\"op\">,</span> <span class=\"nu\">3</span><span class=\"op\">)</span><span class=\"op\">,</span> <span class=\"st\">&quot;|&quot;</span><span class=\"op\">,</span> <span class=\"va\">where</span><span class=\"op\">,</span> <span class=\"st\">&quot;|&quot;</span><span class=\"op\">,</span> <span class=\"va\">document</span><span class=\"op\">.</span><span class=\"va\">page_content</span><span class=\"op\">[</span><span class=\"op\">:</span><span class=\"nu\">65</span><span class=\"op\">]</span><span class=\"op\">,</span> <span class=\"st\">&quot;...&quot;</span><span class=\"op\">)</span>", "", "", "<span class=\"cm\"># ------------------------------------------------------------</span>", "<span class=\"cm\"># STEP 7 : AUGMENT</span>", "<span class=\"cm\"># ------------------------------------------------------------</span>", "", "<span class=\"cm\"># Same string building as Day 22, with the page number added to the header</span>", "<span class=\"cm\"># line of each piece. The model can only cite a page if we show it one.</span>", "", "<span class=\"va\">context</span> <span class=\"op\">=</span> <span class=\"st\">&quot;&quot;</span>", "", "<span class=\"kc\">for</span> <span class=\"va\">document</span><span class=\"op\">,</span> <span class=\"va\">score</span> <span class=\"kc\">in</span> <span class=\"va\">top_chunks</span><span class=\"op\">:</span>", "    <span class=\"va\">where</span> <span class=\"op\">=</span> <span class=\"fn\">describe_source</span><span class=\"op\">(</span><span class=\"va\">document</span><span class=\"op\">.</span><span class=\"va\">metadata</span><span class=\"op\">[</span><span class=\"st\">&quot;source&quot;</span><span class=\"op\">]</span><span class=\"op\">,</span> <span class=\"va\">document</span><span class=\"op\">.</span><span class=\"va\">metadata</span><span class=\"op\">[</span><span class=\"st\">&quot;page&quot;</span><span class=\"op\">]</span><span class=\"op\">)</span>", "    <span class=\"va\">context</span> <span class=\"op\">=</span> <span class=\"va\">context</span> <span class=\"op\">+</span> <span class=\"st\">&quot;From &quot;</span> <span class=\"op\">+</span> <span class=\"va\">where</span> <span class=\"op\">+</span> <span class=\"st\">&quot;:\\n&quot;</span> <span class=\"op\">+</span> <span class=\"va\">document</span><span class=\"op\">.</span><span class=\"va\">page_content</span> <span class=\"op\">+</span> <span class=\"st\">&quot;\\n\\n&quot;</span>", "", "<span class=\"va\">prompt</span> <span class=\"op\">=</span> <span class=\"st\">f&quot;&quot;&quot;</span><span class=\"st\">You are the internal helpdesk assistant for a company called Plural Labs.</span>", "", "<span class=\"st\">Answer the question using ONLY the context given below.</span>", "<span class=\"st\">If the answer is not in the context, say &quot;I could not find this in the Plural Labs documents.&quot;</span>", "<span class=\"st\">Do not use any outside knowledge.</span>", "<span class=\"st\">At the end, mention which file your answer came from, and the page number if there is one.</span>", "", "<span class=\"st\">CONTEXT:</span>", "<span class=\"op\">{</span><span class=\"va\">context</span><span class=\"op\">}</span>", "", "<span class=\"st\">QUESTION:</span>", "<span class=\"op\">{</span><span class=\"va\">question</span><span class=\"op\">}</span>", "", "<span class=\"st\">ANSWER:</span><span class=\"st\">&quot;&quot;&quot;</span>", "", "<span class=\"fn\">print</span><span class=\"op\">(</span><span class=\"st\">&quot;-&quot;</span> <span class=\"op\">*</span> <span class=\"nu\">60</span><span class=\"op\">)</span>", "<span class=\"fn\">print</span><span class=\"op\">(</span><span class=\"st\">&quot;STEP 7 - AUGMENT : prompt built,&quot;</span><span class=\"op\">,</span> <span class=\"fn\">len</span><span class=\"op\">(</span><span class=\"va\">prompt</span><span class=\"op\">)</span><span class=\"op\">,</span> <span class=\"st\">&quot;characters&quot;</span><span class=\"op\">)</span>", "", "", "<span class=\"cm\"># ------------------------------------------------------------</span>", "<span class=\"cm\"># STEP 8 : GENERATE</span>", "<span class=\"cm\"># ------------------------------------------------------------</span>", "", "<span class=\"va\">llm</span> <span class=\"op\">=</span> <span class=\"cl\">ChatGoogleGenerativeAI</span><span class=\"op\">(</span><span class=\"va\">model</span><span class=\"op\">=</span><span class=\"st\">&quot;gemini-3-flash-preview&quot;</span><span class=\"op\">,</span> <span class=\"va\">temperature</span><span class=\"op\">=</span><span class=\"nu\">0</span><span class=\"op\">)</span>", "", "<span class=\"va\">response</span> <span class=\"op\">=</span> <span class=\"va\">llm</span><span class=\"op\">.</span><span class=\"fn\">invoke</span><span class=\"op\">(</span><span class=\"va\">prompt</span><span class=\"op\">)</span>", "", "<span class=\"fn\">print</span><span class=\"op\">(</span><span class=\"st\">&quot;-&quot;</span> <span class=\"op\">*</span> <span class=\"nu\">60</span><span class=\"op\">)</span>", "<span class=\"fn\">print</span><span class=\"op\">(</span><span class=\"st\">&quot;STEP 8 - GENERATE : grounded answer&quot;</span><span class=\"op\">)</span>", "<span class=\"fn\">print</span><span class=\"op\">(</span><span class=\"op\">)</span>", "<span class=\"fn\">print</span><span class=\"op\">(</span><span class=\"va\">response</span><span class=\"op\">.</span><span class=\"va\">text</span><span class=\"op\">)</span>", "", "", "<span class=\"cm\"># ============================================================</span>", "<span class=\"cm\"># WHAT TO TAKE AWAY FROM TODAY</span>", "<span class=\"cm\"># ============================================================</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\"># 1. The retrieval did not get smarter today. The LOADER got wider.</span>", "<span class=\"cm\">#    A RAG system is only as good as the documents it can actually open,</span>", "<span class=\"cm\">#    and that is usually the cheapest part of it to improve.</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\"># 2. A loader is not one function, it is a pipeline. Open the file, pull the</span>", "<span class=\"cm\">#    text out, clean the text, split it into pages, check the result is not</span>", "<span class=\"cm\">#    empty. The cleaning and the checking are not optional extras - the</span>", "<span class=\"cm\">#    ligature problem would have quietly damaged every search for the word</span>", "<span class=\"cm\">#    &quot;office&quot; in our entire company handbook.</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\"># 3. A dictionary of functions turns &quot;support one more format&quot; from a code</span>", "<span class=\"cm\">#    change into a one line addition.</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\"># WHAT IS STILL BROKEN, for next class :</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\">#   - the HTML file is skipped, and when we do load it we must throw away the</span>", "<span class=\"cm\">#     navigation menu, the cookie banner and the JavaScript, or our search</span>", "<span class=\"cm\">#     results will be full of the words &quot;Home HR Portal IT Desk Finance&quot;</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\">#   - the screenshot is skipped, and it cannot be opened by any text library</span>", "<span class=\"cm\">#     at all, because there is no text in it - only a picture of text.</span>", "<span class=\"cm\">#     That one needs a model with eyes.</span>", "<span class=\"cm\">#</span>", "<span class=\"cm\">#   - and we still have not improved the chunking, which is the single</span>", "<span class=\"cm\">#     biggest quality win left in this project.</span>", ""];
window.RAW=window.RAW||{};RAW["day25_rag"]=["# ============================================================", "# DAY 25 : RAG WITH REAL FILES - PART 1, THE PDF", "# ============================================================", "", "# On Day 22 we built the whole RAG machine. Eight steps, start to finish.", "# It worked, but it had one very small line hiding in it :", "#", "#       if not file_name.endswith(\".txt\"):", "#           continue", "#", "# That line is the subject of today's class.", "#", "# A real company does not keep its knowledge in .txt files. It keeps it in", "# PDFs, in Word files, in intranet pages, in screenshots somebody pasted into", "# a chat. Our Day 22 loader walks past every single one of them in silence.", "#", "# Look inside plural_labs_docs right now. There are 4 text files, 3 PDFs,", "# 1 HTML page and 1 screenshot. Day 22 sees 4 files and misses more than half", "# the company's knowledge, and it never prints a single warning while doing it.", "#", "# Today we teach it to read PDFs. The next class adds HTML and images.", "#", "# Only STEP 1 changes today. Steps 2 to 8 are the same machine as Day 22,", "# so the comments on those steps are kept short - you already know them.", "# Everything new is explained in full.", "", "", "# ------------------------------------------------------------", "# BEFORE YOU RUN THIS FILE : INSTALL THE NEW PACKAGE", "# ------------------------------------------------------------", "", "# On Mac, in the terminal :", "#     pip3 install pypdf", "#", "# On Windows, in the command prompt :", "#     pip install pypdf", "# or python3 -m pip install X", "#", "# One package today. pypdf is written in pure Python, so it installs on every", "# machine without needing a compiler. That is exactly why we start with it.", "#", "# You will hear about other PDF libraries - PyMuPDF, pdfplumber. They are", "# faster and they understand page layout better. We will meet PyMuPDF in the", "# screenshot class, because it can turn a PDF page into an image. For reading", "# plain text out of a normal PDF, pypdf is the simplest thing that works.", "", "", "# ------------------------------------------------------------", "# THE IMPORTS", "# ------------------------------------------------------------", "", "import os", "", "# re -> Python's REGULAR EXPRESSION module. This is probably new to you, so", "# here is the whole idea in one paragraph before we use it.", "#", "# You already know how to find exact text :", "#", "#       text.replace(\"cat\", \"dog\")", "#", "# That works when you know exactly what you are looking for. But today we have", "# to fix messes where we do NOT know the exact text. We need to say things like", "# \"wherever there is a run of spaces and newlines, however long it happens to", "# be, squash it down to one space\". You cannot write that with .replace(),", "# because you would have to call it once for two spaces, again for three", "# spaces, again for a newline followed by two spaces, and so on forever.", "#", "# A regular expression - a regex - is a tiny language for describing a SHAPE of", "# text instead of exact text. \"A run of whitespace\" is a shape. \"A digit", "# followed by a colon\" is a shape. The re module is Python's reader for that", "# language, and it is built into Python, so there is nothing to install.", "#", "# We use exactly one function from it today, re.sub, explained where we use it.", "import re", "", "# ---- from pypdf import PdfReader ----", "#", "# Look at this line next to the two lines above it. They are both imports,", "# but they are written in two different shapes, and the difference is worth", "# understanding because you will write both for the rest of your life.", "#", "#       import os                     <- bring in the WHOLE module", "#       from pypdf import PdfReader   <- bring in ONE NAME out of a package", "#", "# With the first shape, everything stays behind its module name, and you must", "# keep saying os.path.join. With the second shape, the one name you asked for", "# is dropped straight into your file, so you write PdfReader(...) on its own", "# rather than pypdf.PdfReader(...).", "#", "# Both work. We use the second here because we need exactly one thing out of", "# pypdf and we mention it twice, so the shorter name is clearer. We use the", "# first for os because we use many different pieces of it.", "#", "# WHERE DID pypdf COME FROM?", "# os and re came with Python. pypdf did not - you installed it yourself with", "# pip, and pip put a folder of Python files somewhere Python knows to look.", "# That is all a \"package\" is : somebody else's Python files on your disk.", "# Nothing magic, and you can go and read them.", "#", "# WHAT IS PdfReader?", "# It is a CLASS, not a function. That capital-letters-joined-together style is", "# how Python programmers signal a class - compare PdfReader with os.listdir.", "# It is a convention, not a rule the language enforces, but it is followed so", "# consistently that you can read a name and know what it is.", "#", "# The practical difference for us : calling a function gives you an answer,", "# but calling a class gives you an OBJECT - a thing that holds state and has", "# its own abilities attached to it. So when we write", "#", "#       reader = PdfReader(path)", "#", "# we are not asking \"give me the text\". We are saying \"open this PDF and give", "# me something I can ask questions of\". Then we ask it things :", "#", "#       reader.pages                 -> the pages of the document", "#       len(reader.pages)            -> how many pages there are", "#       reader.pages[0]              -> the first page", "#       reader.pages[0].extract_text()  -> the text on that page", "#       reader.metadata              -> title, author, created date, if present", "#", "# ONE HONEST DETAIL. reader.pages looks like a list and you can loop over it,", "# count it and index it - but it is not actually a list. pypdf hands back its", "# own object that only parses a page at the moment you reach for it. That is", "# why opening a 500 page PDF is instant : nothing has really been read yet.", "# You do not have to do anything about this. It is simply worth knowing that", "# \"behaves like a list\" and \"is a list\" are different claims in Python, and", "# most code only ever needs the first.", "#", "# AND THE LIMIT THAT MATTERS MOST.", "# extract_text() pulls out the text that is already stored inside the PDF as", "# text. It does not look at the page and recognise letters. If a page is a", "# photograph of a document, there is no text in there to pull, and pypdf", "# returns an empty string - politely, with no error. Our loader checks for", "# exactly that case further down, and the class after this one is about what", "# to do when it happens.", "from pypdf import PdfReader", "", "from langchain_google_genai import ChatGoogleGenerativeAI", "from langchain_google_genai import GoogleGenerativeAIEmbeddings", "from langchain_qdrant import QdrantVectorStore", "from dotenv import load_dotenv", "", "load_dotenv()", "", "folder = \"plural_labs_docs\"", "", "", "# ============================================================", "# STEP 0 : WHY DAY 22 CANNOT SIMPLY READ A PDF", "# ============================================================", "", "# Before we fix anything, let us watch the problem happen.", "# A beginner's first instinct is reasonable : a PDF is a file, open() reads", "# files, so just open it. Let us try that on one of our new PDFs.", "", "print(\"STEP 0 - what happens if we read a PDF the Day 22 way\")", "", "try:", "    with open(os.path.join(folder, \"remote_work_policy.pdf\"), \"r\", encoding=\"utf-8\") as f:", "        f.read()", "except UnicodeDecodeError as error:", "    print(\"    Python refused :\", error)", "", "# Read that error message slowly. \"codec can't decode byte 0xf9\".", "#", "# A .txt file is just letters, one after another. A PDF is not. A PDF is a", "# small compressed database - it holds fonts, images, page sizes, and the text", "# squeezed down into binary. Those bytes are not letters in any alphabet, so", "# Python cannot turn them into a string and it stops.", "#", "# This is actually the GOOD case, because it is loud. It crashes and tells us.", "# Later in this course we will meet the quiet case : a file that opens happily", "# and gives us an empty string. That one is far more dangerous, because the", "# program keeps running and just quietly knows nothing.", "#", "# So we cannot read a PDF ourselves. We need a library that understands the", "# PDF format and unpacks the text for us. That is pypdf.", "", "print(\"-\" * 60)", "", "", "# ============================================================", "# PIPELINE 1 - INDEXING", "# ============================================================", "", "# ------------------------------------------------------------", "# STEP 1 : LOAD - now with more than one file format", "# ------------------------------------------------------------", "", "# This is the whole lesson. Read it in three parts :", "#   part A - a function that cleans up text", "#   part B - one small loader function per file format", "#   part C - a dictionary that picks the right loader", "", "", "# ---------- part A : cleaning the text ----------", "", "def clean_text(text):", "    \"\"\"Tidy up the raw text that a PDF gives us.\"\"\"", "", "    # PROBLEM 1 : ligatures.", "    # Open any PDF of ours and pypdf hands back \"E\ufb00ective\" and \"O\ufb03ce\"", "    # and \"Con\ufb01dential\". Those are not typos and pypdf is not broken.", "    #", "    # When a typesetter puts certain letters next to each other - f and f, or", "    # f and i - the font draws them joined together as ONE single character.", "    # Printers have done this for 500 years because \"ff\" looks cramped.", "    # Unicode kept those joined shapes as real characters of their own.", "    # So inside the PDF, the word \"office\" is genuinely stored as o + \ufb03 + c + e.", "    # Five characters, not six.", "    #", "    # Why we must care : our search works on meaning, but the embedding model", "    # still reads characters. \"O\ufb03ce\" is not the word \"office\" to it. A student", "    # asking about the office could easily miss this chunk. So we translate", "    # those joined characters back into normal letters before anything else.", "    ligatures = {", "        \"\ufb00\": \"ff\",    # as in o\ufb00ice hours, sta\ufb00", "        \"\ufb01\": \"fi\",    # as in con\ufb01dential, bene\ufb01ts", "        \"\ufb02\": \"fl\",    # as in \ufb02exible, re\ufb02ect", "        \"\ufb03\": \"ffi\",   # as in o\ufb03ce, su\ufb03cient", "        \"\ufb04\": \"ffl\",   # as in sha\ufb04e - rare, but costs nothing to handle", "    }", "    for joined_character, normal_letters in ligatures.items():", "        text = text.replace(joined_character, normal_letters)", "", "    # ----------------------------------------------------------------", "    # MEET re.sub - it takes THREE arguments", "    #", "    #       re.sub(pattern, replacement, text)", "    #          |       |          |        |", "    #          |       |          |        +-- the text to work on", "    #          |       |          +----------- what to put instead", "    #          |       +---------------------- the SHAPE to look for", "    #          +------------------------------ \"substitute\"", "    #", "    # It finds every place in the text that matches the shape, and replaces", "    # all of them. Not the first one - every one. You do not write a loop.", "    #", "    # And note how we call it below :", "    #", "    #       text = re.sub(...)", "    #", "    # The result is ASSIGNED BACK to text. re.sub does not change the text you", "    # give it, because strings in Python can never be changed once they exist.", "    # It builds a brand new string and hands it back. If you forget the", "    # \"text =\" part, the function runs perfectly, does all the work, and you", "    # throw the answer away. Nothing crashes. That is a bug students lose", "    # whole evenings to, so look for it first when cleaning seems to do nothing.", "    # ----------------------------------------------------------------", "", "    # PROBLEM 2 : hyphens at the end of a line.", "    #", "    # When a document is justified, a long word gets broken across two lines", "    # with a hyphen : \"reimburse-\" at the end of one line and \"ment\" at the", "    # start of the next. The PDF stores it exactly like that, so pypdf gives us", "    #", "    #       \"reimburse-\\nment\"", "    #", "    # and our search would then be looking for a word that does not exist.", "    # Glue it back together by deleting the hyphen and the newline.", "    #", "    # Reading the pattern r\"-\\n\" :", "    #       -       an ordinary hyphen, matching itself", "    #       \\n      a newline, the invisible character at the end of a line", "    #", "    # The replacement is \"\" - an empty string - which is how you say \"delete", "    # this\" with re.sub. There is no separate delete function; replacing", "    # something with nothing IS deleting it.", "    #", "    # HONESTY NOTE, and a habit worth copying : this rule finds nothing in our", "    # three PDFs. I counted - zero matches - because the tool that made them", "    # does not hyphenate. It fires constantly on PDFs exported from Word or", "    # from LaTeX. Keeping a rule that does nothing today costs us nothing and", "    # saves us the day a student brings in a real company document. But do go", "    # and count, rather than assuming your cleaning worked :", "    #", "    #       print(len(re.findall(r\"-\\n\", raw_text)))", "    text = re.sub(r\"-\\n\", \"\", text)", "", "    # PROBLEM 3 : ragged whitespace. This is the rule that does the real work.", "    #", "    # A PDF does not store sentences. It stores instructions like \"draw these", "    # letters at this position on the page\". So where a sentence happens to", "    # reach the right margin, the PDF simply starts the next line, and pypdf", "    # hands that back to us as a newline sitting in the middle of a sentence.", "    # One of our own pages genuinely contains this :", "    #", "    #       \"Do not turn it off. Your\\nscreen must lock automatically\"", "    #", "    # Our handbook has 45 of those. Column layouts and tables are worse again,", "    # and give long runs of spaces in the middle of a line.", "    #", "    # Reading the pattern r\"\\s+\" :", "    #       \\s      ONE whitespace character - a space, a tab, or a newline", "    #       +       \"one or more of the thing just before me\"", "    #   so  \\s+     a run of whitespace of ANY length, from one to a thousand", "    #", "    # Replacing all of it with a single \" \" turns any mess of spacing into one", "    # ordinary space. \"it off. Your\\nscreen\" becomes \"it off. Your screen\".", "    #", "    # WHY THE LITTLE r BEFORE THE QUOTES?", "    # That r makes it a RAW string, and it is not decoration. Inside a normal", "    # Python string a backslash starts an escape code - \"\\n\" means newline,", "    # \"\\t\" means tab. But \"\\s\" is not an escape code Python knows, and Python", "    # 3.14 will tell you so :", "    #", "    #       SyntaxWarning: \"\\s\" is an invalid escape sequence.", "    #", "    # The r switches that whole system off and passes the characters through", "    # untouched, so the regex engine receives \\ and s and reads them as its own", "    # code for whitespace. Habit to build : if a string is a regex, start it", "    # with r, every time, without thinking about it.", "    text = re.sub(r\"\\s+\", \" \", text)", "", "    # ORDER MATTERS, and this is the kind of thing that makes cleaning code", "    # look simple and behave strangely. Problem 2 must run BEFORE problem 3.", "    # Once problem 3 has turned every newline into a space, \"reimburse-\\nment\"", "    # has already become \"reimburse- ment\", and the pattern r\"-\\n\" can never", "    # match it again. Swap these two lines and the hyphen fix silently stops", "    # working - with no error, which is exactly why you must notice it now.", "", "    # .strip() -> remove leading and trailing spaces", "    return text.strip()", "", "", "# ---------- part B : one loader per file format ----------", "", "# Every loader below follows the SAME contract, and the contract is the point.", "# Each one takes a file path and returns a LIST of dictionaries, where each", "# dictionary is {\"page\": <number or None>, \"text\": <the text>}.", "#", "# Why a list, when a text file has only one piece of text in it?", "# Because a PDF has many. If we return a list from every loader, then the code", "# that calls them never has to care which format it is dealing with. One file", "# gives us one list, whether that list has 1 item or 400.", "#", "# That idea - every loader looks identical from the outside - is what will let", "# us add HTML and images next class by writing one function and changing", "# nothing else in this file.", "", "", "def load_txt(path):", "    \"\"\"Read a plain text file. This is Day 22's loader, unchanged.\"\"\"", "    with open(path, \"r\", encoding=\"utf-8\") as file:", "        text = file.read()", "", "    # page is None because a text file has no pages. Nothing to number.", "    # We will handle that None when we print the source at the end.", "    return [{\"page\": None, \"text\": clean_text(text)}]", "", "", "def load_pdf(path):", "    \"\"\"Read a PDF, one entry per page.\"\"\"", "", "    # PdfReader opens the file and understands its structure for us.", "    reader = PdfReader(path)", "", "    pages = []", "", "    # reader.pages behaves like a list of page objects.", "    # enumerate(..., start=1) gives us the position as we go, counting from 1", "    # instead of 0 - because a human reading page one calls it page 1.", "    for page_number, page in enumerate(reader.pages, start=1):", "", "        # extract_text() -> pulls the text out of that one page.", "        # It can return None for a page that has no text layer at all,", "        # so \"or empty string\" protects us from a crash on the next line.", "        raw_text = page.extract_text() or \"\"", "", "        text = clean_text(raw_text)", "", "        # THE EMPTY PAGE CHECK.", "        # If a page gives us almost nothing, something is wrong with it.", "        # Usually it means the page is a SCANNED IMAGE - somebody photocopied", "        # a document and saved the photo inside a PDF. There are no letters in", "        # that file at all, only a picture of letters. pypdf is not failing;", "        # there is genuinely nothing there for it to find.", "        #", "        # We cannot fix that today, but we must never let it pass in silence.", "        # An empty chunk in our database is worse than no chunk, because it", "        # still takes up one of the 3 slots our search returns.", "        # Next class we send pages like this to a vision model to be read.", "        if len(text) < 100:", "            print(\"    WARNING :\", os.path.basename(path), \"page\", page_number,", "                  \"gave only\", len(text), \"characters - is it a scan?\")", "            continue", "", "        pages.append({\"page\": page_number, \"text\": text})", "", "    return pages", "", "", "# ---------- part C : the dictionary that chooses ----------", "", "# Here is the idea that replaces Day 22's if-statement.", "#", "# We already know a dictionary can hold numbers or strings as its values.", "# A dictionary can also hold FUNCTIONS as its values. Look carefully at what", "# is written below : load_txt, with no brackets after it.", "#", "#     load_txt()  -> brackets mean CALL the function right now, give me the result", "#     load_txt    -> no brackets means the function ITSELF, as a value", "#", "# So LOADERS is a dictionary from a file extension to the function that knows", "# how to read it. People call this a dispatch table, or a registry.", "#", "# Why this is better than a chain of if-elif-elif :", "#   - adding a format is adding ONE line, not editing a growing if-block", "#   - the list of what we support is visible in one place, at a glance", "#   - the loop below never mentions pdf or txt at all, so it never changes", "", "LOADERS = {", "    \".txt\": load_txt,", "    \".md\":  load_txt,   # a markdown file is plain text too, so the same loader works", "    \".pdf\": load_pdf,", "}", "", "", "# ---------- and now the loading loop ----------", "", "documents = []", "", "for file_name in sorted(os.listdir(folder)):", "", "    # os.path.splitext splits a name into two parts at the last dot.", "    # \"remote_work_policy.pdf\" becomes (\"remote_work_policy\", \".pdf\")", "    # The [1] takes the second part, the extension.", "    # .lower() because a file called NOTES.PDF must work exactly the same way.", "    extension = os.path.splitext(file_name)[1].lower()", "", "    # .get() asks the dictionary for a value WITHOUT crashing if the key is", "    # missing. A plain LOADERS[extension] would raise KeyError on our .html", "    # file. .get() returns None instead, and we can deal with None ourselves.", "    loader = LOADERS.get(extension)", "", "    if loader is None:", "        # Day 22 skipped these silently. We refuse to. A loud skip is a to-do", "        # list - it is literally printing next class's homework on the screen.", "        print(\"    skipping\", file_name, \"- no loader for\", extension, \"yet\")", "        continue", "", "    file_path = os.path.join(folder, file_name)", "", "    # THE CALL. Note that we do not write load_pdf(file_path) anywhere.", "    # We write loader(file_path), and the dictionary already decided which", "    # function \"loader\" is. This one line reads every format we support.", "    pieces = loader(file_path)", "", "    # Each loader gave us a list. We attach the file name to every piece and", "    # collect them all into one flat list of documents.", "    for piece in pieces:", "        documents.append({", "            \"source\": file_name,", "            \"page\":   piece[\"page\"],", "            \"text\":   piece[\"text\"],", "        })", "", "    print(\"    loaded\", file_name, \"->\", len(pieces), \"piece(s)\")", "", "print(\"STEP 1 - LOAD :\", len(documents), \"pieces of text from\", folder)", "", "", "# A small helper for printing where something came from.", "# A PDF piece can say \"page 2\". A text file piece cannot, so it just says the", "# file name. This is the one place that None has to be handled, and we keep it", "# in a function so the rest of the file stays clean.", "def describe_source(source, page):", "    if page is None:", "        return source", "    return source + \" page \" + str(page)", "", "", "print(\"-\" * 60)", "", "", "# ------------------------------------------------------------", "# STEP 2 : CHUNK", "# ------------------------------------------------------------", "", "# Same 60-word cutting as Day 22. We are deliberately not improving the", "# chunking today - one change per class, so you can always see what caused", "# what. Chunking gets a full class of its own next.", "#", "# ONE thing is new here, and it is small but important. In Day 22 the label", "# carried only the file name. Now it carries the page number too, and it", "# carries it all the way through the database to the final answer. That is how", "# our bot will be able to say \"page 2\" instead of just naming a 40 page PDF", "# and leaving you to search it yourself.", "#", "# Notice also that because we loaded page by page, a chunk can never contain", "# text from two different pages. The page split did half of our chunking for", "# us, for free.", "", "chunk_size = 60", "", "chunk_texts = []", "chunk_labels = []", "", "for document in documents:", "    words = document[\"text\"].split()", "", "    for start in range(0, len(words), chunk_size):", "        piece_text = \" \".join(words[start:start + chunk_size])", "", "        chunk_texts.append(piece_text)", "        chunk_labels.append({", "            \"source\": document[\"source\"],", "            \"page\":   document[\"page\"],      # <- the new part", "        })", "", "print(\"STEP 2 - CHUNK : cut into\", len(chunk_texts), \"chunks\")", "", "", "# ------------------------------------------------------------", "# STEP 3 and 4 : EMBED and STORE", "# ------------------------------------------------------------", "", "# Unchanged from Day 22. Qdrant calls the embedding model for every chunk and", "# stores each vector together with its label.", "", "embedding_model = GoogleGenerativeAIEmbeddings(model=\"gemini-embedding-001\")", "", "vector_db = QdrantVectorStore.from_texts(", "    texts=chunk_texts,", "    embedding=embedding_model,", "    metadatas=chunk_labels,", "    collection_name=\"plural_labs\",", "    location=\":memory:\",", ")", "", "print(\"STEP 3 and 4 - EMBED and STORE : Qdrant ready with\", len(chunk_texts), \"vectors\")", "print(\"-\" * 60)", "", "", "# ============================================================", "# PIPELINE 2 - ANSWERING", "# ============================================================", "", "# THE QUESTION.", "# This exact question was the last demo of Day 22, and Day 22 could not answer", "# it. Our bot correctly refused, because the work from home rules were simply", "# not in any of the four text files.", "#", "# Nothing about our retrieval or our prompt has improved since then. The only", "# thing that changed is that the loader can now open a PDF. Watch the same", "# question get a real answer.", "", "question = \"Can I work from home permanently at Plural Labs?\"", "", "# In class, try these one at a time.", "", "# Needs page 1 of the remote work PDF :", "# question = \"How much is the home office setup allowance and by when must I claim it?\"", "", "# Needs the IT security PDF :", "# question = \"How long before my laptop screen locks, and can I change it?\"", "", "# Needs the insurance PDF :", "# question = \"Are my parents covered by the company health insurance?\"", "", "# A text file question, to prove we did not break Day 22 while adding PDFs :", "# question = \"How many paid leaves do I get in a year?\"", "", "# This one crosses TWO files - the leave policy text file and the remote work", "# PDF. Watch how it handles needing evidence from both :", "# question = \"I am a new joiner. Can I work remotely, and how many leaves do I get?\"", "", "# And the honesty test again. Notice period is in none of our 9 files,", "# not even the new ones. It must still refuse.", "# question = \"What is the notice period if I resign from Plural Labs?\"", "", "print(\"QUESTION :\", question)", "print(\"-\" * 60)", "", "", "# ------------------------------------------------------------", "# STEP 5 and 6 : RETRIEVE and RANK", "# ------------------------------------------------------------", "", "top_chunks = vector_db.similarity_search_with_score(question, k=3)", "", "print(\"STEP 5 and 6 - RETRIEVE and RANK : the 3 winning chunks are\")", "", "for document, score in top_chunks:", "    # metadata[\"page\"] is the page number we carried all the way from STEP 1.", "    where = describe_source(document.metadata[\"source\"], document.metadata[\"page\"])", "    print(\"   \", round(score, 3), \"|\", where, \"|\", document.page_content[:65], \"...\")", "", "", "# ------------------------------------------------------------", "# STEP 7 : AUGMENT", "# ------------------------------------------------------------", "", "# Same string building as Day 22, with the page number added to the header", "# line of each piece. The model can only cite a page if we show it one.", "", "context = \"\"", "", "for document, score in top_chunks:", "    where = describe_source(document.metadata[\"source\"], document.metadata[\"page\"])", "    context = context + \"From \" + where + \":\\n\" + document.page_content + \"\\n\\n\"", "", "prompt = f\"\"\"You are the internal helpdesk assistant for a company called Plural Labs.", "", "Answer the question using ONLY the context given below.", "If the answer is not in the context, say \"I could not find this in the Plural Labs documents.\"", "Do not use any outside knowledge.", "At the end, mention which file your answer came from, and the page number if there is one.", "", "CONTEXT:", "{context}", "", "QUESTION:", "{question}", "", "ANSWER:\"\"\"", "", "print(\"-\" * 60)", "print(\"STEP 7 - AUGMENT : prompt built,\", len(prompt), \"characters\")", "", "", "# ------------------------------------------------------------", "# STEP 8 : GENERATE", "# ------------------------------------------------------------", "", "llm = ChatGoogleGenerativeAI(model=\"gemini-3-flash-preview\", temperature=0)", "", "response = llm.invoke(prompt)", "", "print(\"-\" * 60)", "print(\"STEP 8 - GENERATE : grounded answer\")", "print()", "print(response.text)", "", "", "# ============================================================", "# WHAT TO TAKE AWAY FROM TODAY", "# ============================================================", "#", "# 1. The retrieval did not get smarter today. The LOADER got wider.", "#    A RAG system is only as good as the documents it can actually open,", "#    and that is usually the cheapest part of it to improve.", "#", "# 2. A loader is not one function, it is a pipeline. Open the file, pull the", "#    text out, clean the text, split it into pages, check the result is not", "#    empty. The cleaning and the checking are not optional extras - the", "#    ligature problem would have quietly damaged every search for the word", "#    \"office\" in our entire company handbook.", "#", "# 3. A dictionary of functions turns \"support one more format\" from a code", "#    change into a one line addition.", "#", "# WHAT IS STILL BROKEN, for next class :", "#", "#   - the HTML file is skipped, and when we do load it we must throw away the", "#     navigation menu, the cookie banner and the JavaScript, or our search", "#     results will be full of the words \"Home HR Portal IT Desk Finance\"", "#", "#   - the screenshot is skipped, and it cannot be opened by any text library", "#     at all, because there is no text in it - only a picture of text.", "#     That one needs a model with eyes.", "#", "#   - and we still have not improved the chunking, which is the single", "#     biggest quality win left in this project.", ""];
